(()=>{'use strict';
const step=(n,title,body)=>`<article class="pb-card"><span class="pb-num">${n}</span><h4>${title}</h4>${body}</article>`;
const samples={
tutorial:`<h3>Fertige Bildanleitung: Einen gezielten Screenshot in OneNote einfügen</h3><p><b>Für wen:</b> Lernende mit Windows und einem bereits geöffneten Schulnotizbuch. <b>Ziel:</b> Auf einer OneNote-Seite steht ein lesbarer Bildausschnitt mit einer passenden Beschriftung.</p><p class="pb-caption">Die folgenden Ansichten sind vereinfachte Schemas, keine Screenshots. Erstellen Sie für Ihre eigene Anleitung eigene Bildschirmaufnahmen.</p><div class="pb-grid">${step(1,'Die richtige Ansicht öffnen','<div class="pb-screen"><div class="pb-top">Browser · MedienInfoLab</div><div class="pb-selection">Woche 45<br>Projektauswahl</div></div><p>Öffnen Sie Woche 45. Scrollen Sie zum Abschnitt «Projektauswahl». Schliessen Sie Fenster mit privaten Angaben. <b>Kontrolle:</b> Nur die gewünschte Seite ist sichtbar.</p>')}${step(2,'Den Ausschnitt aufnehmen','<div class="pb-screen"><div class="pb-keys">⊞ + Umschalt + S</div><div class="pb-selection">Nur den benötigten Bereich markieren</div></div><p>Drücken Sie Windows + Umschalt + S. Wählen Sie den rechteckigen Ausschnitt und ziehen Sie einen Rahmen um den gewünschten Bereich. <b>Kontrolle:</b> Das Bild liegt in der Zwischenablage.</p>')}${step(3,'Auf der OneNote-Seite einfügen','<div class="pb-screen"><div class="pb-top">OneNote · Meine Anleitung</div><div class="pb-keys">Ctrl + V</div><div class="pb-miniimage">Ihr Bildausschnitt</div></div><p>Wechseln Sie zur Zielseite in OneNote. Klicken Sie auf eine freie Stelle und drücken Sie Ctrl + V. <b>Kontrolle:</b> Der Ausschnitt steht auf der Seite.</p>')}${step(4,'Bildgrösse und Erklärung ergänzen','<div class="pb-screen"><div class="pb-miniimage">Projekte auf Woche 45</div><p>Hier wählen Sie einen Auftrag aus.</p></div><p>Ziehen Sie an einer Ecke des Bildes, bis der Text gut lesbar ist. Schreiben Sie darunter: «Hier wählen Sie einen Auftrag aus.» <b>Kontrolle:</b> Die Proportionen stimmen und der Zweck ist erklärt.</p>')}${step(5,'Die Seite wiederfinden und prüfen','<div class="pb-screen"><div class="pb-top">Meine Anleitung</div><div class="pb-miniimage">Bild und Erklärung sind lesbar ✓</div></div><p>Wechseln Sie kurz auf eine andere Seite und wieder zurück. Prüfen Sie Bild und Beschriftung. <b>Kontrolle:</b> Beides ist vorhanden. Warten Sie bei der Schul-Cloud auf die Synchronisierung.</p>')}</div><p><b>Fiktiver Ohne-Hilfe-Test:</b> Die Testperson fügte zuerst in die falsche Seite ein. Deshalb nennt Schritt 3 jetzt ausdrücklich die Zielseite. Beim zweiten Versuch gelang der Ablauf. <b>Fehlerhilfe:</b> Ist das Bild nicht in der Zwischenablage, nehmen Sie den Ausschnitt erneut auf und fügen ihn sofort ein.</p>`,
cockpit:`<h3>Fertiges Cockpit · fiktive Übungswoche</h3><div class="pb-grid"><article class="pb-card"><h4>Meine nächsten Aufgaben</h4><p>✓ Drei Scan-Seiten in eine PDF bringen.</p><p>☐ PDF öffnen und Reihenfolge B–C–A prüfen.</p><p>☐ In der App auf Folie 3 den Button mit Folie 4 verlinken.</p></article><article class="pb-card"><h4>Meine nächsten Termine</h4><p><b>5. November 2026, 10.00 Uhr:</b> Übungs-PDF selbst kontrollieren.</p><p><b>6. November 2026, 16.00 Uhr:</b> App-Zwischenstand sichern.</p><p class="pb-caption">Erfundene Termine, keine verbindlichen Schulabgaben.</p></article><article class="pb-card"><h4>Meine Schnellzugriffe</h4><p><a href="woche45.html">Woche 45 und mein Arbeitsstand</a></p><p><a href="projekte.html">Projektwerkstatt</a></p><p><a href="digipen-guide.html">DigiPen-Hilfe</a></p></article><article class="pb-card"><h4>Mein erreichbares Ziel</h4><p>Bis Freitag, 6. November, habe ich den Hauptweg meiner fünf App-Ansichten getestet.</p><p><b>Erster Handgriff:</b> Auf Folie 3 «Abholort ansehen» mit Folie 4 verbinden.</p></article></div><p><b>Nutzungsregel:</b> Am Stundenanfang ansehen, am Schluss abhaken.</p><p><b>Fiktiver Alltagstest:</b> Die Testperson fand den nächsten Auftrag sofort, suchte aber den Link zum Kurs. Ich habe «Hier» in «Woche 45 und mein Arbeitsstand» geändert. Der Link lässt sich nun eindeutig zuordnen.</p>`,
dokumente:`<h3>Fertiges Beispieldossier · Open-Air Nord</h3><p><a class="pb-link" href="assets/week45/Beispiel-Open-Air-Dossier.pdf" target="_blank" rel="noopener">Vollständige Muster-PDF öffnen (3 Seiten)</a></p><div class="pb-grid"><article class="pb-card"><h4>Seite 1 · Tagesinfo (B)</h4><p>Zuerst kläre ich, wann und wo der Tag stattfindet: 15. August 2027 im Wiesenpark, Beginn 14.00 Uhr.</p></article><article class="pb-card"><h4>Seite 2 · Anreise (C)</h4><p>Danach plane ich den Weg: Treffpunkt 12.20 Uhr am Bahnhof Musterhausen. Der Regionalzug fährt um 12.35 Uhr.</p></article><article class="pb-card"><h4>Seite 3 · Packliste (A)</h4><p>Zum Schluss packe ich: Bei Regen gehört eine Regenjacke oder ein Regenponcho dazu.</p></article></div><p><b>Fertiger Qualitätscheck:</b> Die Reihenfolge B–C–A folgt den Fragen «Was ist geplant? Wie komme ich hin? Was nehme ich mit?». Die Datei enthält drei aufrechte Seiten. Alle Überschriften und kleinen Angaben sind lesbar. Beginn 14.00 Uhr auf Seite 1, Zugabfahrt 12.35 Uhr auf Seite 2 und Regenschutz auf Seite 3 sind auffindbar. Die Musterdatei heisst «Beispiel-Open-Air-Dossier.pdf» und ist 47’916 Byte gross (rund 48 kB).</p><p><b>Muster-Speicherort:</b> OneDrive → Informatik → Projekte → Dossier Alex. Die eigene Datei muss nach dem Speichern erneut geöffnet und geprüft werden. Alle Orte und Zeiten sind erfunden.</p>`,
faktencheck:`<h3>Fertige Faktencheck-Karte · Inkognito = unsichtbar?</h3><p><b>Behauptung:</b> «Im Inkognitomodus kann niemand sehen, welche Webseiten ich besuche.» <b>Ursprung:</b> erfundene Behauptung aus diesem Unterrichtsauftrag. <b>Prüffrage:</b> Macht privates Browsen gegenüber Webseiten und dem Netzwerk anonym?</p><div class="pb-grid"><article class="pb-card"><h4>Beleg 1 · Google Chrome-Hilfe</h4><p>Die Hilfe erklärt, dass Chrome nach Ende einer Inkognito-Sitzung bestimmte lokale Browserdaten nicht behält. Besuchte Webseiten sowie Schule, Arbeitgeber oder Internetanbieter können Aktivitäten dennoch möglicherweise beobachten.</p><p><a href="https://support.google.com/chrome/answer/95464?hl=de" target="_blank" rel="noopener">Quelle: Im Inkognitomodus surfen</a><br>Fundstelle: Abschnitt zur begrenzten Speicherung auf dem Gerät und zur Sichtbarkeit für andere. Abruf: 02.11.2026.</p></article><article class="pb-card"><h4>Beleg 2 · Mozilla Firefox-Hilfe</h4><p>Auch Mozilla unterscheidet private Fenster von Anonymität im Internet. Privates Browsen reduziert lokal gespeicherte Spuren, macht Nutzende aber nicht unsichtbar.</p><p><a href="https://support.mozilla.org/en-US/kb/private-browsing-use-firefox-without-history" target="_blank" rel="noopener">Quelle: Private Browsing – Use Firefox without saving history</a><br>Fundstelle: Hinweis «Important» am Anfang. Abruf: 02.11.2026.</p></article></div><p><b>Gegenprüfung:</b> Google und Mozilla sind verschiedene Organisationen. Beide beschreiben die Funktion ihres eigenen Browsers. Es handelt sich nicht um zwei Abschriften derselben Nachricht.</p><p><b>Urteil: falsch.</b> Das Wort «niemand» behauptet vollständige Unsichtbarkeit. Beide Quellen widersprechen diesem Teil. Private Fenster können lokale Spuren reduzieren, ersetzen aber keine Anonymität. <b>Grenze:</b> Welche konkreten Daten jemand sehen kann, hängt unter anderem von Verbindung, Netzwerk und Anmeldung ab. Die Quellen beweisen nicht, dass jede besuchte Seite stets den vollständigen Inhalt eines Besuchs erkennt.</p><p><b>Ergebnis:</b> Eine Karte mit genauer Behauptung, zwei nachvollziehbaren Belegen und begründetem Urteil. Bearbeiten Sie für Ihre eigene Karte einen eigenen Fall oder prüfen Sie den Startfall selbst anhand der Originalquellen.</p>`,
lifehacks:`<h3>Fertige Tricksammlung · fünf Handgriffe unter Windows</h3><p>Die Testnotizen sind ausgearbeitete <b>Muster</b>. Führen Sie die Handgriffe selbst aus und beschreiben Sie Ihren eigenen Test.</p><div class="pb-grid">${[
['Auf einer Seite suchen','Ctrl + F','Öffnen Sie Woche 45. Drücken Sie Ctrl + F. Geben Sie «Protokoll» ein und wechseln Sie durch die Treffer.','Das Suchfeld zeigt Treffer auf der Seite.','Text in Bildern wird dabei nicht zuverlässig gefunden.'],
['Einen geschlossenen Tab zurückholen','Ctrl + Umschalt + T','Öffnen Sie einen zusätzlichen gewöhnlichen Browser-Tab. Schliessen Sie ihn mit dem Kreuz. Drücken Sie Ctrl + Umschalt + T.','Der zuletzt geschlossene Tab erscheint wieder.','Verlassen Sie sich dabei nicht auf private Fenster oder ungespeicherte Formulare.'],
['Zwei Fenster vergleichen','⊞ + ← / →','Öffnen Sie zwei Fenster. Wählen Sie das erste und drücken Sie Windows + Pfeil links. Wählen Sie das zweite für die rechte Seite.','Auftrag und Ergebnis sind gleichzeitig sichtbar.','Bei sehr kleinen Displays werden Texte eng. Dann wechseln Sie besser zwischen den Fenstern.'],
['Einen Ausschnitt aufnehmen','⊞ + Umschalt + S','Zeigen Sie eine unpersönliche Übungsseite. Drücken Sie Windows + Umschalt + S und ziehen Sie den Ausschnitt auf. Fügen Sie ihn mit Ctrl + V in OneNote ein.','Nur der gewählte Bereich steht im Notizbuch.','Die Zwischenablage kann überschrieben werden. Fügen Sie den Ausschnitt zeitnah ein.'],
['Eine Änderung rückgängig machen','Ctrl + Z','Schreiben Sie in einer eigenen Übungsnotiz «Probe». Löschen Sie das Wort. Drücken Sie Ctrl + Z.','Das gelöschte Wort ist wieder da.','Dies funktioniert nicht für jede Handlung und nicht überall gleich. Testen Sie nur an eigenen Übungsdaten.']
].map((r,i)=>step(i+1,r[0],`<div class="pb-keys">${r[1]}</div><p><b>Anleitung:</b> ${r[2]}</p><p><b>Muster-Testnachweis:</b> ${r[3]}</p><p><b>Grenze:</b> ${r[4]}</p>`)).join('')}</div><p><b>Mein Favorit im Muster:</b> Zwei Fenster nebeneinander, weil ich Anleitung und Ergebnis direkt vergleichen kann. <b>Fiktive Verbesserung nach dem Ohne-Hilfe-Test:</b> Bei Tipp 3 fehlte, welches Fenster zuerst gewählt werden soll. Das steht jetzt ausdrücklich dabei.</p><p class="pb-caption">Quellen: <a href="https://support.microsoft.com/de-de/accessibility/windows/keyboard-shortcuts-in-windows" target="_blank" rel="noopener">Microsoft · Tastenkombinationen in Windows</a> und <a href="https://support.google.com/chrome/answer/157179?hl=de" target="_blank" rel="noopener">Google · Chrome-Tastenkombinationen</a>.</p>`,
nachrichten:`<h3>Vollständiges Antwortmuster zu den drei Grundfällen</h3><div class="pb-grid">${step('A','Die Paket-SMS','<p><b>Entscheidung:</b> Nichts anklicken oder senden.</p><p><b>Beleg:</b> Ich erwarte kein Paket. Die Nachricht fordert CHF 2.90 bis heute 18 Uhr und setzt mich damit unter Zeitdruck.</p><p><b>Nächster Schritt:</b> Falls ich eine Sendung prüfen will, öffne ich die bekannte offizielle Paket-Webseite selbst. Ich verwende nicht den SMS-Link.</p>')}${step('B','Die selbst ausgelöste Kontomeldung','<p><b>Entscheidung:</b> Im bereits geöffneten offiziellen Dienst fortfahren.</p><p><b>Beleg:</b> Ich habe die Passwortänderung gerade selbst angefordert. Die Meldung fordert weder mein Passwort als Antwort noch eine Zahlung.</p><p><b>Nächster Schritt:</b> Ich bleibe im selbst geöffneten Browserfenster. Der angezeigte Absender allein wäre noch kein Echtheitsbeweis.</p>')}${step('C','Der angebliche Gewinn','<p><b>Entscheidung:</b> Nicht antworten und keine Angaben senden.</p><p><b>Beleg:</b> Ich habe nicht teilgenommen. Gefordert werden ein Ausweisfoto und ein SMS-Code unter Zeitdruck.</p><p><b>Nächster Schritt:</b> Ich melde und blockiere den Kontakt über die Plattform. Bei Bedarf prüfe ich den Veranstalter über einen unabhängig gefundenen offiziellen Kanal.</p>')}</div><p><b>Was gute Antworten gemeinsam haben:</b> eine Entscheidung, ein genauer Hinweis aus dem Fall und eine ausführbare nächste Handlung. Formulieren Sie Ihre Antworten selbst.</p>`,
bildausschnitt:`<h3>Vollständiges Vergleichsbeispiel</h3><div class="pb-grid"><figure class="pb-card"><div class="pb-crop narrow" role="img" aria-label="Enger Ausschnitt aus dem KI-Übungsbild"></div><h4>«Ein Becher neben der Bank»</h4><p>Dieser enge Ausschnitt zeigt einen kleinen Teil der Szene. Der Zusammenhang mit den anderen Helfenden und ihren Sammelsäcken fehlt. Wer nur diesen Ausschnitt sieht, könnte die Situation als liegengelassenen Abfall auffassen.</p></figure><figure class="pb-card"><img src="assets/parkbild.jpg" alt="Ganzes KI-Übungsbild der Sammelaktion"><h4>«Gemeinsam Abfall sammeln»</h4><p>Das ganze Bild zeigt mehrere Personen mit Handschuhen, Greifzangen und Säcken. Zusammen mit der Aufgabenbeschreibung spricht das für eine Sammelaktion. Man kann nun die Person am linken Bildrand in diesen Zusammenhang einordnen.</p></figure></div><p><b>Sichtbar:</b> mehrere Personen, Abfall und Sammelmaterial. <b>Unsicher:</b> Ein Einzelbild beweist nicht sicher, ob die Hand einen Gegenstand gerade aufhebt oder hinlegt. Das KI-Bild dokumentiert kein echtes Ereignis.</p><p><b>Muster-Verbesserung:</b> Die erste Überschrift «Jemand wirft Abfall weg» hätte eine nicht belegte Handlung behauptet. «Ein Becher neben der Bank» bleibt beim Sichtbaren.</p>`,
plakat:`<h3>Vollständiges Muster · ein übersichtlicher Aushang</h3><div class="pb-poster"><span>TAUSCHEN STATT KAUFEN</span><h4>Kleider<br>tausch</h4><p><b>Samstag, 21. November 2026<br>14–17 Uhr</b></p><p>Jugendtreff Nord</p><p>Höchstens fünf saubere<br>Kleidungsstücke mitbringen.</p><b>Eintritt frei</b><small>Erfundener Übungsanlass</small></div><ol><li>Der Anlass steht als grösster Text oben. So weiss man sofort, wofür der Aushang wirbt.</li><li>Datum und Zeit stehen zusammen. So findet man die Angaben zum Besuch an einer Stelle.</li><li>Die Mitbringregel hat einen eigenen Bereich. So bleiben «höchstens fünf» und «sauber» gut lesbar, ohne den Anlass zu verdrängen.</li></ol><p><b>Musterprüfung:</b> Anlass, Datum, Zeit, Ort, Mitbringen und Eintritt sind vollständig. Eine eigene Version darf anders angeordnet sein.</p>`,
storyboard:`<h3>Vollständiges Storyboard · Wo ist der Schlüssel?</h3><p><b>Idee:</b> Eine Person sucht den Schlüssel, der die ganze Zeit am Rucksack hängt.</p><div class="pb-grid">${[
['Übersicht','Eine Person mit Rucksack steht vor einer geschlossenen Haustür. Sie greift zur Jackentasche.'],['Detail','Die Hand zieht die Jackentasche auf. Darin liegt kein Schlüssel.'],['Nah','Die Person sucht in der zweiten Tasche und schaut zur geschlossenen Tür.'],['Detail','Am Rucksackriemen hängt sichtbar ein Schlüssel. Die Hand hält kurz inne.'],['Nah','Die Person blickt zum Rucksackriemen und nimmt den Schlüssel ab.'],['Detail','Der Schlüssel dreht sich im Schloss. Die Tür öffnet sich.']
].map((r,i)=>step(i+1,r[0],`<p>${r[1]}</p>`)).join('')}</div><p><b>Zwei begründete Ausschnitte:</b> Szene 1 zeigt mit einer Übersicht Person, Rucksack und Tür. Damit ist die Ausgangslage klar. Szene 4 zeigt den Schlüssel im Detail, weil die Lösung sonst leicht übersehen wird.</p><p><b>Verbesserung nach dem Muster-Selbsttest:</b> In Szene 6 stand zuerst nur «Die Person ist erleichtert». Jetzt öffnet sich die Tür sichtbar. So versteht man das Ende ohne Erklärung.</p>`
};
function mount(){const main=document.querySelector('main');if(!main)return;const file=location.pathname.split('/').pop().replace(/\.html$/,'');const id=file==='projekt'?new URLSearchParams(location.search).get('thema'):location.hash.slice(1).split('/')[0];
 if(file==='projekte'&&!samples[id])return;
 if(!samples[id]||main.querySelector('[data-project-boost="'+id+'"]'))return;
 const host=document.createElement('section');host.className='pb-support';host.dataset.projectBoost=id;host.innerHTML=`<details><summary>Vollständige Musterlösung ansehen · ${id==='faktencheck'?'mit Belegen und Urteil':'mit fertigen Texten und Erklärung'}</summary><div class="pb-example">${samples[id]}<p class="pb-caption">Das Beispiel zeigt eine mögliche vollständige Lösung. Es ersetzt Ihre eigene Bearbeitung und Ihre eigenen Tests nicht.</p></div></details><details><summary>So arbeiten Sie ohne zusätzliche Erklärung weiter</summary><ol><li>Öffnen Sie einen Schritt und lesen Sie zuerst das verlangte Ergebnis.</li><li>Führen Sie die Handlungen nacheinander aus. Bei Bedarf öffnen Sie die Hilfe direkt im Schritt.</li><li>Vergleichen Sie Ihr Ergebnis mit der Musterlösung und den Qualitätskriterien.</li><li>Fehlt eine Testperson? Machen Sie nach einer kurzen Pause einen Selbsttest und kennzeichnen Sie ihn so.</li><li>Speichern Sie den Arbeitsstand und die Ergebnisdatei. Nutzen Sie am Schluss den Knopf «Stopp &amp; Protokoll» unten rechts.</li></ol></details>`;
 const anchor=file==='projekt'?main.querySelector('#projectApp .notice'):main.querySelector('.project-content');if(anchor){if(file==='projekt')anchor.insertAdjacentElement('afterend',host);else anchor.prepend(host);}else main.prepend(host);

}
let queued=false;function schedule(){if(queued)return;queued=true;queueMicrotask(()=>{queued=false;mount();});}
function start(){mount();new MutationObserver(schedule).observe(document.querySelector('main'),{childList:true,subtree:true});window.addEventListener('hashchange',schedule);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
